def transform(grid):
    """Mark cells occupied in both panels, separated by a solid line."""
    h, w = len(grid), len(grid[0])
    # A full, nonzero, uniform row/column is the panel separator.
    separators = []
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            separators.append((r, "row"))
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            separators.append((c, "col"))
    # A genuine divider splits the grid into equally sized panels; incidental
    # uniform lines inside a panel (e.g. a solid pattern column) are ignored.
    balanced = []
    for pos, axis in separators:
        if axis == "row" and pos == h - pos - 1:
            balanced.append((pos, axis))
        elif axis == "col" and pos == w - pos - 1:
            balanced.append((pos, axis))
    if len(balanced) != 1:
        raise ValueError("expected one centered solid separator")
    pos, axis = balanced[0]
    if axis == "row":
        top, bottom = grid[:pos], grid[pos + 1:]
        if len(top) != len(bottom):
            raise ValueError("panels must have equal height")
        if any(len(row) != w for row in top + bottom):
            raise ValueError("ragged grid")
        return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                for ra, rb in zip(top, bottom)]
    left_w, right_w = pos, w - pos - 1
    if left_w != right_w:
        raise ValueError("panels must have equal width")
    return [[2 if grid[r][c] != 0 and grid[r][pos + 1 + c] != 0 else 0
             for c in range(left_w)] for r in range(h)]
